import os, pty, select, signal, subprocess, time
master, slave = pty.openpty()
cmd=['make','monitor','PORT=/dev/cu.usbserial-1130']
p=subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, start_new_session=True, close_fds=True)
os.close(slave); os.set_blocking(master, False)
buf=bytearray(); end=time.time()+18
while time.time()<end and p.poll() is None:
    ready,_,_=select.select([master],[],[],0.2)
    if ready:
        try: data=os.read(master,65536)
        except (BlockingIOError,OSError): data=b''
        if data: buf.extend(data)
    if b'esp-idf-monitor' in buf:
        time.sleep(8)
        break
if p.poll() is None:
    os.killpg(p.pid, signal.SIGTERM)
    try: p.wait(timeout=3)
    except subprocess.TimeoutExpired: os.killpg(p.pid, signal.SIGKILL); p.wait()
try: os.close(master)
except OSError: pass
out=buf.decode('utf-8', errors='replace')
print('MONITOR_STARTED', 'esp-idf-monitor' in out)
print('ROM_BOOT_MARKER', 'ESP-ROM:esp32s3' in out)
print('POWERON_MARKER', 'rst:0x1 (POWERON)' in out)
for line in out.splitlines():
    if 'esp-idf-monitor' in line or 'ESP-ROM:esp32s3' in line or 'rst:0x' in line:
        print(line)
assert 'esp-idf-monitor' in out
assert 'ESP-ROM:esp32s3' not in out
assert 'rst:0x1 (POWERON)' not in out
